var DEFAULT_MAX_ATTEMPTS = 2;

// gh-775: hard wall-clock cap for the bounded missing-response resume.
// 40 min by recommendation — must fit the job's remaining timeout budget;
// projects can tighten it via feedbackLoop.missingResponse.timeoutSeconds.
var DEFAULT_MISSING_RESPONSE_TIMEOUT_SECONDS = 2400;

// gh-775: dedicated attempt-marker stage so the bounded resume never shares
// (or consumes) the failure-recovery stages' attempt counters.
var MISSING_RESPONSE_STAGE = 'missing_response';

function sanitizeId(value) {
    return String(value || 'unknown').replace(/[^A-Za-z0-9_.-]+/g, '_');
}

function writeFile(path, content) {
    file_write({ path: path, content: content });
}

function readFile(path) {
    try { return file_read({ path: path }); } catch (e) { return null; }
}

function runCommand(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function ensureFeedbackDir() {
    // mkdir is not in the cli_execute_command whitelist — wrap in bash -c.
    try { runCommand('bash -c "mkdir -p outputs/feedback"'); } catch (e) {}
}

function normalizeConfig(customParams, section) {
    var root = (customParams && customParams.feedbackLoop) || {};
    var scoped = (section && root[section] && typeof root[section] === 'object') ? root[section] : {};
    var merged = {};
    Object.keys(root).forEach(function(key) {
        if (typeof root[key] !== 'object' || Array.isArray(root[key])) merged[key] = root[key];
    });
    Object.keys(scoped).forEach(function(key) { merged[key] = scoped[key]; });
    return merged;
}

function isFeedbackEnabled(customParams, section) {
    var root = (customParams && customParams.feedbackLoop) || null;
    if (!root) return false;
    var scoped = (section && root[section] && typeof root[section] === 'object') ? root[section] : null;
    return root.enabled === true || (scoped && scoped.enabled === true);
}

function getAttempt(markerPath) {
    var raw = readFile(markerPath);
    var value = parseInt(raw || '0', 10);
    return isNaN(value) ? 0 : value;
}

function setAttempt(markerPath, attempt) {
    writeFile(markerPath, String(attempt));
}

function isNonRecoverable(errorText, config) {
    var text = String(errorText || '');
    var patterns = (config && config.nonRecoverablePatterns) || [
        'COPILOT_GITHUB_TOKEN',
        'GITHUB_TOKEN',
        'JIRA_API_TOKEN',
        'Bad credentials',
        'Resource not accessible by integration',
        'could not read Username',
        'Authentication failed',
        'refusing to merge unrelated histories',
        'No merge base found between HEAD and origin/'
    ];
    return patterns.some(function(pattern) {
        return text.indexOf(pattern) !== -1;
    });
}

function buildFeedbackPrompt(options) {
    return [
        'A previous automation step failed. Continue/resume the current task in the same repository and fix the root cause.',
        '',
        'Ticket: ' + (options.ticketKey || 'unknown'),
        'Stage: ' + (options.stage || 'unknown'),
        'Attempt: ' + (options.attempt || 1),
        '',
        'Error/output:',
        '```',
        String(options.error || '').substring(0, 12000),
        '```',
        '',
        'Instructions:',
        '- Inspect the current working tree and recent changes.',
        '- Fix the failure directly; do not revert unrelated user or automation changes.',
        '- Keep the implementation focused on the ticket and the failing gate/post-action.',
        '- Update outputs/response.md with what you changed and any validation you ran.',
        '- Do not push; the post-action will commit and push after you finish.'
    ].join('\n');
}

// gh-775: follow-up prompt for the bounded missing-response resume — the exact
// scenario this recovery exists for is a hung background verification child
// that stalled the session after the real work was done (live fa gh-1341).
// Kept inline like buildFeedbackPrompt (the prompts/ home variant would add a
// runtime file-read failure mode for no versioning benefit — this file IS the
// versioned home of the resume mechanics).
function buildMissingResponsePrompt(options) {
    options = options || {};
    return [
        'Your previous run finished its real work but was interrupted before outputs/response.md could be written — most likely a background verification job (test suite, coverage, build) hung and the session stalled watching it.',
        '',
        'Ticket: ' + (options.ticketKey || 'unknown'),
        '',
        'Resume and finish the task now:',
        '- Check running background jobs (bash_job status) and STOP any job with no progress: bash_job stop <id>.',
        '- Do NOT restart long verification runs. Note the unverified part in the deliverable (job id, command, last output tail) — validation CI on the pull request is the safety net.',
        '- Finish any remaining small steps, then write outputs/response.md (the deliverable the post-action expects) and end the turn.',
        '- Do not push; the post-action will commit and push after you finish.'
    ].join('\n');
}

function resumeAgent(options) {
    options = options || {};
    var customParams = options.customParams || {};
    var config = normalizeConfig(customParams, options.section || 'postAction');
    if (!isFeedbackEnabled(customParams, options.section || 'postAction') || config.enabled === false) {
        return { attempted: false, reason: 'disabled' };
    }

    var maxAttempts = config.maxAttempts;
    if (maxAttempts === undefined || maxAttempts === null) maxAttempts = DEFAULT_MAX_ATTEMPTS;
    maxAttempts = parseInt(maxAttempts, 10);
    if (!maxAttempts || maxAttempts < 1) return { attempted: false, reason: 'maxAttempts=0' };

    var errorText = String(options.error || '');
    if (isNonRecoverable(errorText, config)) {
        return { attempted: false, reason: 'non-recoverable' };
    }

    ensureFeedbackDir();
    var key = sanitizeId((options.ticketKey || 'unknown') + '_' + (options.stage || 'feedback'));
    var markerPath = 'outputs/feedback/' + key + '.attempt';
    var attempt = getAttempt(markerPath);
    if (attempt >= maxAttempts) {
        return { attempted: false, reason: 'attempts-exhausted', attempts: attempt };
    }

    attempt += 1;
    setAttempt(markerPath, attempt);

    // `buildFeedbackPrompt()` bakes in dev-flow assumptions ("do not push; the
    // post-action will commit and push after you finish") that don't apply to
    // every caller (e.g. a publish-only post-action that never pushes code).
    // Callers with a different resume flow can pass `promptOverride` with the
    // full prompt text instead — attempt tracking / non-recoverable-error
    // detection / the `--continue` resume mechanics stay identical either way.
    var prompt = options.promptOverride || buildFeedbackPrompt({
        ticketKey: options.ticketKey,
        stage: options.stage,
        attempt: attempt,
        error: errorText
    });
    var promptPath = 'outputs/feedback/' + key + '.md';
    writeFile(promptPath, prompt);

    // Copilot CLI's `--continue` already means "resume the most recent session in this
    // directory" (no value needed); its own `-r, --resume[=value]` flag is a second,
    // mutually exclusive way to resume (by explicit id or an interactive picker when bare).
    // Passing both together is rejected outright: "error: option '-r, --resume[=value]'
    // cannot be used with option '--continue'" — which made every feedback-loop retry fail
    // deterministically before the agent ever got a chance to act on the new prompt.
    var resumeArgs = config.resumeArgs || '--continue';
    var command = 'bash agents/scripts/run-agent.sh ' + resumeArgs + ' ' + promptPath;
    // gh-775: bounded resume — a hard wall-clock cap on the wrapper invocation so a
    // hung provider session cannot hold the post-action (and the job's remaining
    // timeout budget) hostage. `timeout -k 60 <N>` TERM-inates the wrapper after <N>
    // seconds and KILLs it 60s later if TERM is ignored. The wrapper is entered
    // through `bash` (cli_execut…

/**
 * quotaCircuitBreaker.js — gh-1087 quota circuit-breaker (pure logic, no dmtools globals).
 *
 * A hard provider-quota failure (HTTP 403 usage-limit / billing body — e.g.
 * "weekly (7-day) usage limit" — or a "Provider chain exhausted" tail that
 * follows quota responses) must PARK the leg lane instead of burning a
 * per-tick retry against a wall that cannot succeed until the quota window
 * resets. Transient interruptions (429 rate-limit blips, timeouts, network
 * cuts) keep the classic gh-742 reset-for-retry behavior.
 *
 * Everything here is a pure function so the classifier, the park decision,
 * the SM dispatch-lane exclusion and the probe cadence are unit-testable
 * without any tracker/CLI mocks:
 *
 *   classifyFailure(text)              → { kind: 'quota_exhausted' | 'transient' | null, ... }
 *   parkLabelOf(jobParams)             → park label name (default 'provider_quota')
 *   probeEveryOf(jobParams)            → probe cadence in SM ticks (default 3)
 *   probeCommandOf(jobParams)          → cheap provider ping shell command
 *   redactCommand(command)             → log-safe probe command (credentials masked)
 *   probeDue(completedTicks, everyN)   → is a probe due this tick?
 *   tickMarkerLine(n)                  → durable per-tick cadence marker line
 *   probeMarkerLine(n)                 → durable per-probe counter line
 *   countTickMarkers(bodies)           → park ticks already recorded
 *   countProbeMarkers(bodies)          → probe attempts already recorded
 *   shouldSkipForQuotaPark(t,rule,jp)  → SM dispatch-lane exclusion predicate
 *   parkComment(m, cls, label, everyN) → ticket/PR park comment (markup-object driven)
 *   unparkComment(m, label, count)     → probe-success un-park comment
 */

var DEFAULT_PARK_LABEL = 'provider_quota';
var DEFAULT_PROBE_EVERY_TICKS = 3;

// Hard-quota bodies: usage-limit / quota / billing vocabulary. A bare 403 is
// NOT enough (some gateways answer 403 for auth too) — the quota vocabulary
// (or an exhausted-chain tail, see classifyFailure) must corroborate it.
var QUOTA_BODY_RE = /usage\s*limit|quota|billing|insufficient\s+(?:credit|quota|balance)|credit[s]?\s+exhausted|plan\s+limit|spend\s+limit/i;
var FORBIDDEN_RE = /\b403\b/;
var CHAIN_EXHAUSTED_RE = /provider chain exhausted/i;
// Transient signals — a retry CAN plausibly succeed on the next tick.
var RATE_LIMIT_RE = /\b429\b/i;
var TIMEOUT_RE = /rate\s*limit|timeout|timed?\s*out|econnreset|etimedout|socket hang up|network error|temporar/i;

function extractQuotaWindow(text) {
    var m = /((?:weekly|daily|monthly|hourly|yearly)(?:\s*\([^)]*\))?)\s+(?:usage\s+)?limit/i.exec(text);
    if (m) return m[1];
    m = /((?:7|14|24|30)-day)\s+(?:usage\s+)?limit/i.exec(text);
    if (m) return m[1];
    m = /(usage\s+limit)\s+((?:weekly|daily|monthly|hourly|yearly)(?:\s*\([^)]*\))?)/i.exec(text);
    if (m) return m[2];
    return null;
}

function extractProvider(text) {
    // Live shape: z.ai glm-5.3-flash answered 403 "weekly (7-day) usage limit"
    var m = /([a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z]{2,})+)\s+[\w.-]+\s+(?:answered|returned|responded with)\s+403/i.exec(text);
    if (m) return m[1];
    m = /provider\s*[:\["']+\s*([A-Za-z0-9._-]+)/i.exec(text);
    if (m) return m[1];
    m = /(?:^|[\s"'(])([a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.(?:ai|com|dev|io|net|org))\b/i.exec(text);
    if (m) return m[1];
    return null;
}

function classifyFailure(text) {
    var t = String(text || '');
    if (!t.trim()) return null;
    var window = extractQuotaWindow(t);
    // Quota ALWAYS wins over transient signals — a mixed chain (429 retries
    // first, 403 usage-limit last) is a quota wall, not a blip.
    if (hasQuotaEvidence(t, window)) {
        return {
            kind: 'quota_exhausted',
            provider: extractProvider(t),
            window: window,
            evidence: quotaEvidenceOf(t)
        };
    }
    if (RATE_LIMIT_RE.test(t) || TIMEOUT_RE.test(t)) {
        return { kind: 'transient', provider: extractProvider(t), window: null, evidence: null };
    }
    return null;
}

// Quota evidence: a 403 carrying a quota/billing body, an explicit quota
// window, or an exhausted-provider-chain tail that follows quota/403
// responses.
function hasQuotaEvidence(t, window) {
    var has403 = FORBIDDEN_RE.test(t);
    var quotaBody = QUOTA_BODY_RE.test(t);
    return (has403 && quotaBody) || window || (CHAIN_EXHAUSTED_RE.test(t) && (quotaBody || has403));
}

function quotaEvidenceOf(t) {
    if (FORBIDDEN_RE.test(t)) return 'HTTP 403';
    if (CHAIN_EXHAUSTED_RE.test(t)) return 'provider chain exhausted';
    return 'usage limit';
}

function parkLabelOf(jobParams) {
    var label = jobParams && jobParams.quotaParkLabel;
    return (typeof label === 'string' && label.trim()) ? label.trim() : DEFAULT_PARK_LABEL;
}

function probeEveryOf(jobParams) {
    var n = jobParams && parseInt(jobParams.quotaProbeEveryNTicks, 10);
    return (n > 0) ? n : DEFAULT_PROBE_EVERY_TICKS;
}

/**
 * Cheap provider ping — one minimal chat completion against the fa provider
 * config (FA_PROVIDER_BASE_URL / FA_PROVIDER_API_KEY / FA_PROVIDER_MODEL).
 * curl --fail makes a 403 quota wall exit non-zero, so a still-exhausted
 * provider keeps the park. Projects using another provider shape override the
 * whole command via jobParams.quotaProbeCommand.
 */
function probeCommandOf(jobParams) {
    var cmd = jobParams && jobParams.quotaProbeCommand;
    if (typeof cmd === 'string' && cmd.trim()) return cmd;
    return 'bash -c \'curl --fail -sS -m 30 -o /dev/null -X POST "$FA_PROVIDER_BASE_URL/chat/completions" ' +
        '-H "Authorization: Bearer $FA_PROVIDER_API_KEY" -H "Content-Type: application/json" ' +
        '-d "{\\"model\\":\\"$FA_PROVIDER_MODEL\\",\\"messages\\":[{\\"role\\":\\"user\\",\\"content\\":\\"ping\\"}],\\"max_tokens\\":1}"\'';
}

// Sensitive header / credential shapes that must never reach SM job logs or
// CI artifacts when an operator overrides jobParams.quotaProbeCommand with an
// inline secret (e.g. -H "Authorization: Bearer sk-...").
var SENSITIVE_VALUE_RE = /((?:authorization|x-api-key|api[-_]?key|token|secret)[\w-]*\s*[:=]\s*(?:bearer\s+)?"?)([^\s'"]+)("?)/gi;
var ENV_REF_RE = /^\$[\w{}]/;

/**
 * gh-1087 review thread 2: the probe command is logged on every probe. The
 * default only references env-var NAMES ($FA_PROVIDER_API_KEY — safe), but a
 * free-form operator override may inline a credential. Mask sensitive values
 * while leaving env-var references (and the safe default) untouched.
 */
function redactCommand(command) {
    return String(command || '').replace(SENSITIVE_VALUE_RE, function (match, prefix, value, suffix) {
        if (ENV_REF_RE.test(value)) return match;
        return prefix + '***' + suffix;
    });
}

// Probe cadence is TICK-based, not attempts-based (gh-1087 review thread 1):
// every SM tick the probe handler records a lightweight 'quota-park-tick: n'
// marker on the ticket, so the completed-tick count advances even between
// probes. A probe fires when the completed tick count is a multiple of
// everyN (0 = first tick after the park — a misclassification self-corrects
// immediately). An attempts-only counter would deadlock: after the first
// failed probe the count is 1 forever and 1 % N never fires probe #2.
function probeDue(completedTicks, everyN) {
    var n = (typeof everyN === 'number' && everyN > 0) ? everyN : DEFAULT_PROBE_EVERY_TICKS;
    return (completedTicks % n) === 0;
}

function tickMarkerLine(count) {
    return 'quota-park-tick: ' + count;
}

function probeMarkerLine(count) {
    return 'quota-probe: ' + count;
}

