function maxMarkerNumber(bodies, markerRe) {
    var count = 0;
    var list = Array.isArray(bodies) ? bodies : [];
    for (var i = 0; i < list.length; i++) {
        var body = String((list[i] && (list[i].body || list[i])) || '');
        markerRe.lastIndex = 0;
        var m;
        while ((m = markerRe.exec(body)) !== null) {
