var OUTAGE_CODE_RE = /\b(5\d{2}|429)\b/g;
var OUTAGE_MODEL_RES = [
   /([A-Za-z0-9][\w.-]*(?:\/[\w.-]+)+)\s+(?:returned|responded with|answered|failed with|hit)\s+(?:HTTP\/?\s*)?(?:5\d{2}|429)/gi,
   /(?:^|[\s"'(])([A-Za-z0-9][\w-]{2,})\s+(?:then\s+)?hit\s+(?:HTTP\/?\s*)?(?:5\d{2}|429)/gi,
