function collectMatches(text, re, cap) {
    var found = [];
    var seen = {};
    re.lastIndex = 0;
    var m;
    while ((m = re.exec(text)) !== null) {
        var value = m[1];
        if (value && !seen[value]) {
            seen[value] = true;
            found.push(value);
            if (found.length >= cap) break;
        }
    }
    re.lastIndex = 0;
    return found;
}

