function classifyFailure(text) {
   var t = String(text || '');
   if (!t.trim()) return null;
   var window = extractQuotaWindow(t);
   // Quota ALWAYS wins ... (unchanged, I1)
   if (hasQuotaEvidence(t, window)) {
       return { kind: 'quota_exhausted', ... };
   }
